/bin/bash -lc "python3 -B - <<'PY'
from pathlib import Path
import subprocess,re,json,ast
run=lambda *a: subprocess.run(['git',*a],capture_output=True).stdout.decode()
materials={p:Path(p).read_text() for p in ['proposed-message.txt','pr-title.txt','pr-body.txt','pr-comment.txt','attachment.txt']}
materials['staged:config.json']=run('show',':config.json')
commits=run('rev-list','--reverse','publication-base..HEAD').splitlines()
for c in commits:
 materials[c+':message']=run('show','-s','--format=%B',c)
 for p in run('ls-tree','-r','--name-only',c).splitlines():
  if Path(p).name"'!='"'README.human.md':materials[c+':'+p]=run('show',c+':'+p)
 materials[c+':diff']=run('diff-tree','--root','-p',c)
materials['staged:diff']=run('diff','--cached','--no-ext-diff','--no-textconv')
# Find credential-shaped assignments entirely in process. Values never leave this process.
pat=re.compile(r'(?i)(?:[\\w-]*(?:password|passwd|api_key|token|secret)[\\w-]*)[\\s\"\\x27]*[:=][\\s\"\\x27]*(["'^'"\\s\"\\x27,;}]+)')
candidates=[]
for p,t in materials.items():
 for m in pat.finditer(t):
  v=m.group(1)
  masked=bool(re.fullmatch(r'(?:REDACTED|CHANGEME|<["'^>]*>|'"\\*+|\\[REDACTED\\])',v,re.I))
  print('credential-assignment',p,'line',t.count('\\n',0,m.start())+1,'status','placeholder' if masked else 'candidate')
  if not masked:candidates.append(v)
# Helper source is parsed, never executed. Inspect all embedded constants for credential assignments.
helper=Path('fixture.py').read_text(); tree=ast.parse(helper)
helper_strings=[n.value for n in ast.walk(tree) if isinstance(n,ast.Constant) and isinstance(n.value,str)]
for t in helper_strings:
 for m in pat.finditer(t):
  v=m.group(1)
  if not re.fullmatch(r'(?:REDACTED|CHANGEME|<["'^>]*>|'"\\*+)',v,re.I):candidates.append(v)
for p,t in materials.items():
 hits=set(v for v in candidates if v in t)
 print('credential-value-crossmatch',p,'count',len(hits))
for p in ['pr-title.txt','pr-comment.txt','attachment.txt']:
 t=materials[p]
 print('classified-sensitive-customer-material',p,'nonempty',bool(t.strip()),'lines',len(t.splitlines()))
print('helper','fixture.py','parsed',True,'executed',False)
PY"

